Mesh<Point, double> edges;
std::vector<std::vector<std::size_t>> const& facets = rt.facets();
std::vector<Point> const& vertices = rt.vertices();

for (std::size_t i = 0; i < facets.size(); ++i) {
    std::vector<std::size_t> const& facet = facets[i];
    if (facet.size() != 3) continue;  // Skip non-triangular facets

    // Get dual vertices (circumcenters) for each edge of the facet
    for (std::size_t j = 0; j < 3; ++j) {
        std::size_t k = (j + 1) % 3;
        std::size_t a = facet[j];
        std::size_t b = facet[k];

        // Get circumcenter of edge (a,b) - in CGAL, this is the dual vertex
        Point dual_a = rt.dual(a);
        Point dual_b = rt.dual(b);

        // Calculate edge length (power distance)
        double power_dist = std::sqrt(std::pow(dual_a.x() - dual_b.x(), 2) +
                                      std::pow(dual_a.y() - dual_b.y(), 2) +
                                      std::pow(dual_a.z() - dual_b.z(), 2));

        // Add edge if it meets threshold (or always add if threshold <= 0)
        if (threshold <= 0 || power_dist >= threshold) {
            edges.add_edge(dual_a, dual_b);
        }
    }
}

// Add face areas (using facet circumradius as area proxy)
for (std::size_t i = 0; i < facets.size(); ++i) {
    std::vector<std::size_t> const& facet = facets[i];
    if (facet.size() != 3) continue;

    // Get circumradius (area proxy) of the facet
    double area = rt.facet_circumradius(i);
    edges.add_face(vertices[facet[0]], vertices[facet[1]], vertices[facet[2]], area);
}
